{"code":"def transform(grid):
    h,w=len(grid),len(grid[0])
    # find a solid rectangular frame (at least 3x3), typically unique
    for color in range(10):
        for t in range(h):
            for b in range(t+2,h):
                for l in range(w):
                    for r in range(l+2,w):
                        if all(grid[t][c]==color for c in range(l,r+1)) and all(grid[b][c]==color for c in range(l,r+1)) and all(grid[x][l]==color and grid[x][r]==color for x in range(t,b+1)):
                            return [row[l+1:r] for row in grid[t+1:b]]
    return grid"}

